class Solution {
  public int maximumSum(int[] nums) {
    int[][] top = new int[3][3];
    for (int x : nums) {
      int[] t = top[x % 3];
      if (x > t[0]) {
        t[2] = t[1];
        t[1] = t[0];
        t[0] = x;
      } else if (x > t[1]) {
        t[2] = t[1];
        t[1] = x;
      } else if (x > t[2]) t[2] = x;
    }
    int best = 0;
    for (int r = 0; r < 3; r++)
      if (top[r][2] > 0) best = Math.max(best, top[r][0] + top[r][1] + top[r][2]);
    if (top[0][0] > 0 && top[1][0] > 0 && top[2][0] > 0)
      best = Math.max(best, top[0][0] + top[1][0] + top[2][0]);
    return best;
  }
}
